func (v EventsValue) ToObjectValue(ctx context.Context) (basetypes.ObjectValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	params := types.ListValueMust(
		ParamsType{
			basetypes.ObjectType{
				AttrTypes: ParamsValue{}.AttributeTypes(ctx),
			},
		},
		v.Params.Elements(),
	)

	if v.Params.IsNull() {
		params = types.ListNull(
			ParamsType{
				basetypes.ObjectType{
					AttrTypes: ParamsValue{}.AttributeTypes(ctx),
				},
			},
		)
	}

	if v.Params.IsUnknown() {
		params = types.ListUnknown(
			ParamsType{
				basetypes.ObjectType{
					AttrTypes: ParamsValue{}.AttributeTypes(ctx),
				},
			},
		)
	}

	var actionsVal basetypes.ListValue
	switch {
	case v.Actions.IsUnknown():
		actionsVal = types.ListUnknown(types.StringType)
	case v.Actions.IsNull():
		actionsVal = types.ListNull(types.StringType)
	default:
		var d diag.Diagnostics
		actionsVal, d = types.ListValue(types.StringType, v.Actions.Elements())
		diags.Append(d...)
	}

	if diags.HasError() {
		return types.ObjectUnknown(map[string]attr.Type{
			"actions": basetypes.ListType{
				ElemType: types.StringType,
			},
			"allow_pipeline_triggered": basetypes.BoolType{},
			"branch_pattern":           basetypes.StringType{},
			"build":                    basetypes.StringType{},
			"cron":                     basetypes.StringType{},
			"params": basetypes.ListType{
				ElemType: ParamsValue{}.Type(ctx),
			},
			"paths": basetypes.ListType{
				ElemType: types.StringType,
			},
			"tag_pattern": basetypes.StringType{},
			"type":        basetypes.StringType{},
		}), diags
	}

	var pathsVal basetypes.ListValue
	switch {
	case v.Paths.IsUnknown():
		pathsVal = types.ListUnknown(types.StringType)
	case v.Paths.IsNull():
		pathsVal = types.ListNull(types.StringType)
	default:
		var d diag.Diagnostics
		pathsVal, d = types.ListValue(types.StringType, v.Paths.Elements())
		diags.Append(d...)
	}

	if diags.HasError() {
		return types.ObjectUnknown(map[string]attr.Type{
			"actions": basetypes.ListType{
				ElemType: types.StringType,
			},
			"allow_pipeline_triggered": basetypes.BoolType{},
			"branch_pattern":           basetypes.StringType{},
			"build":                    basetypes.StringType{},
			"cron":                     basetypes.StringType{},
			"params": basetypes.ListType{
				ElemType: ParamsValue{}.Type(ctx),
			},
			"paths": basetypes.ListType{
				ElemType: types.StringType,
			},
			"tag_pattern": basetypes.StringType{},
			"type":        basetypes.StringType{},
		}), diags
	}

	attributeTypes := map[string]attr.Type{
		"actions": basetypes.ListType{
			ElemType: types.StringType,
		},
		"allow_pipeline_triggered": basetypes.BoolType{},
		"branch_pattern":           basetypes.StringType{},
		"build":                    basetypes.StringType{},
		"cron":                     basetypes.StringType{},
		"params": basetypes.ListType{
			ElemType: ParamsValue{}.Type(ctx),
		},
		"paths": basetypes.ListType{
			ElemType: types.StringType,
		},
		"tag_pattern": basetypes.StringType{},
		"type":        basetypes.StringType{},
	}

	if v.IsNull() {
		return types.ObjectNull(attributeTypes), diags
	}

	if v.IsUnknown() {
		return types.ObjectUnknown(attributeTypes), diags
	}

	objVal, diags := types.ObjectValue(
		attributeTypes,
		map[string]attr.Value{
			"actions":                  actionsVal,
			"allow_pipeline_triggered": v.AllowPipelineTriggered,
			"branch_pattern":           v.BranchPattern,
			"build":                    v.Build,
			"cron":                     v.Cron,
			"params":                   params,
			"paths":                    pathsVal,
			"tag_pattern":              v.TagPattern,
			"type":                     v.EventsType,
		})

	return objVal, diags
}

func (v EventsValue) Equal(o attr.Value) bool {
	other, ok := o.(EventsValue)

	if !ok {
		return false
	}

	if v.state != other.state {
		return false
	}

	if v.state != attr.ValueStateKnown {
		return true
	}

	if !v.Actions.Equal(other.Actions) {
		return false
	}

	if !v.AllowPipelineTriggered.Equal(other.AllowPipelineTriggered) {
		return false
	}

	if !v.BranchPattern.Equal(other.BranchPattern) {
		return false
	}

	if !v.Build.Equal(other.Build) {
		return false
	}

	if !v.Cron.Equal(other.Cron) {
		return false
	}

	if !v.Params.Equal(other.Params) {
		return false
	}

	if !v.Paths.Equal(other.Paths) {
		return false
	}

	if !v.TagPattern.Equal(other.TagPattern) {
		return false
	}

	if !v.EventsType.Equal(other.EventsType) {
		return false
	}

	return true
}

