func NewParamsValue(attributeTypes map[string]attr.Type, attributes map[string]attr.Value) (ParamsValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	// Reference: https://github.com/hashicorp/terraform-plugin-framework/issues/521
	ctx := context.Background()

	for name, attributeType := range attributeTypes {
		attribute, ok := attributes[name]

		if !ok {
			diags.AddError(
				"Missing ParamsValue Attribute Value",
				"While creating a ParamsValue value, a missing attribute value was detected. "+
					"A ParamsValue must contain values for all attributes, even if null or unknown. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("ParamsValue Attribute Name (%s) Expected Type: %s", name, attributeType.String()),
			)

			continue
		}

		if !attributeType.Equal(attribute.Type(ctx)) {
			diags.AddError(
				"Invalid ParamsValue Attribute Type",
				"While creating a ParamsValue value, an invalid attribute value was detected. "+
					"A ParamsValue must use a matching attribute type for the value. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("ParamsValue Attribute Name (%s) Expected Type: %s\n", name, attributeType.String())+
					fmt.Sprintf("ParamsValue Attribute Name (%s) Given Type: %s", name, attribute.Type(ctx)),
			)
		}
	}

	for name := range attributes {
		_, ok := attributeTypes[name]

		if !ok {
			diags.AddError(
				"Extra ParamsValue Attribute Value",
				"While creating a ParamsValue value, an extra attribute value was detected. "+
					"A ParamsValue must not contain values beyond the expected attribute types. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("Extra ParamsValue Attribute Name: %s", name),
			)
		}
	}

	if diags.HasError() {
		return NewParamsValueUnknown(), diags
	}

	defaultAttribute, ok := attributes["default"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`default is missing from object`)

		return NewParamsValueUnknown(), diags
	}

	defaultVal, ok := defaultAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`default expected to be basetypes.StringValue, was: %T`, defaultAttribute))
	}

	descriptionAttribute, ok := attributes["description"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`description is missing from object`)

		return NewParamsValueUnknown(), diags
	}

	descriptionVal, ok := descriptionAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`description expected to be basetypes.StringValue, was: %T`, descriptionAttribute))
	}

	nameAttribute, ok := attributes["name"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`name is missing from object`)

		return NewParamsValueUnknown(), diags
	}

	nameVal, ok := nameAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`name expected to be basetypes.StringValue, was: %T`, nameAttribute))
	}

	optionsAttribute, ok := attributes["options"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`options is missing from object`)

		return NewParamsValueUnknown(), diags
	}

	optionsVal, ok := optionsAttribute.(basetypes.ListValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`options expected to be basetypes.ListValue, was: %T`, optionsAttribute))
	}

	requiredAttribute, ok := attributes["required"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`required is missing from object`)

		return NewParamsValueUnknown(), diags
	}

	requiredVal, ok := requiredAttribute.(basetypes.BoolValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`required expected to be basetypes.BoolValue, was: %T`, requiredAttribute))
	}

	typeAttribute, ok := attributes["type"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`type is missing from object`)

		return NewParamsValueUnknown(), diags
	}

	typeVal, ok := typeAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`type expected to be basetypes.StringValue, was: %T`, typeAttribute))
	}

	if diags.HasError() {
		return NewParamsValueUnknown(), diags
	}

	return ParamsValue{
		Default:     defaultVal,
		Description: descriptionVal,
		Name:        nameVal,
		Options:     optionsVal,
		Required:    requiredVal,
		ParamsType:  typeVal,
		state:       attr.ValueStateKnown,
	}, diags
}

func NewParamsValueMust(attributeTypes map[string]attr.Type, attributes map[string]attr.Value) ParamsValue {
	object, diags := NewParamsValue(attributeTypes, attributes)

	if diags.HasError() {
		// This could potentially be added to the diag package.
		diagsStrings := make([]string, 0, len(diags))

		for _, diagnostic := range diags {
			diagsStrings = append(diagsStrings, fmt.Sprintf(
				"%s | %s | %s",
				diagnostic.Severity(),
				diagnostic.Summary(),
				diagnostic.Detail()))
		}

		panic("NewParamsValueMust received error(s): " + strings.Join(diagsStrings, "\n"))
	}

	return object
}

func (t ParamsType) ValueFromTerraform(ctx context.Context, in tftypes.Value) (attr.Value, error) {
	if in.Type() == nil {
		return NewParamsValueNull(), nil
	}

	if !in.Type().Equal(t.TerraformType(ctx)) {
		return nil, fmt.Errorf("expected %s, got %s", t.TerraformType(ctx), in.Type())
	}

	if !in.IsKnown() {
		return NewParamsValueUnknown(), nil
	}

	if in.IsNull() {
		return NewParamsValueNull(), nil
	}

	attributes := map[string]attr.Value{}

	val := map[string]tftypes.Value{}

	err := in.As(&val)

	if err != nil {
		return nil, err
	}

	for k, v := range val {
		a, err := t.AttrTypes[k].ValueFromTerraform(ctx, v)

		if err != nil {
			return nil, err
		}

		attributes[k] = a
	}

	return NewParamsValueMust(ParamsValue{}.AttributeTypes(ctx), attributes), nil
}

func (t ParamsType) ValueType(ctx context.Context) attr.Value {
	return ParamsValue{}
}

var _ basetypes.ObjectValuable = ParamsValue{}

type ParamsValue struct {
	Default     basetypes.StringValue `tfsdk:"default"`
	Description basetypes.StringValue `tfsdk:"description"`
	Name        basetypes.StringValue `tfsdk:"name"`
	Options     basetypes.ListValue   `tfsdk:"options"`
	Required    basetypes.BoolValue   `tfsdk:"required"`
	ParamsType  basetypes.StringValue `tfsdk:"type"`
	state       attr.ValueState
}

func (v ParamsValue) ToTerraformValue(ctx context.Context) (tftypes.Value, error) {
	attrTypes := make(map[string]tftypes.Type, 6)

	var val tftypes.Value
	var err error

	attrTypes["default"] = basetypes.StringType{}.TerraformType(ctx)
	attrTypes["description"] = basetypes.StringType{}.TerraformType(ctx)
	attrTypes["name"] = basetypes.StringType{}.TerraformType(ctx)
	attrTypes["options"] = basetypes.ListType{
		ElemType: types.StringType,
	}.TerraformType(ctx)
	attrTypes["required"] = basetypes.BoolType{}.TerraformType(ctx)
	attrTypes["type"] = basetypes.StringType{}.TerraformType(ctx)

	objectType := tftypes.Object{AttributeTypes: attrTypes}

	switch v.state {
	case attr.ValueStateKnown:
		vals := make(map[string]tftypes.Value, 6)

		val, err = v.Default.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["default"] = val

		val, err = v.Description.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["description"] = val

		val, err = v.Name.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["name"] = val

		val, err = v.Options.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["options"] = val

		val, err = v.Required.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["required"] = val

		val, err = v.ParamsType.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["type"] = val

		if err := tftypes.ValidateValue(objectType, vals); err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		return tftypes.NewValue(objectType, vals), nil
	case attr.ValueStateNull:
		return tftypes.NewValue(objectType, nil), nil
	case attr.ValueStateUnknown:
		return tftypes.NewValue(objectType, tftypes.UnknownValue), nil
	default:
		panic(fmt.Sprintf("unhandled Object state in ToTerraformValue: %s", v.state))
	}
}

func (v ParamsValue) IsNull() bool {
	return v.state == attr.ValueStateNull
}

func (v ParamsValue) IsUnknown() bool {
	return v.state == attr.ValueStateUnknown
}

func (v ParamsValue) String() string {
	return "ParamsValue"
}

func (v ParamsValue) ToObjectValue(ctx context.Context) (basetypes.ObjectValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	var optionsVal basetypes.ListValue
	switch {
	case v.Options.IsUnknown():
		optionsVal = types.ListUnknown(types.StringType)
	case v.Options.IsNull():
		optionsVal = types.ListNull(types.StringType)
	default:
		var d diag.Diagnostics
		optionsVal, d = types.ListValue(types.StringType, v.Options.Elements())
		diags.Append(d...)
	}

	if diags.HasError() {
		return types.ObjectUnknown(map[string]attr.Type{
			"default":     basetypes.StringType{},
			"description": basetypes.StringType{},
			"name":        basetypes.StringType{},
			"options": basetypes.ListType{
				ElemType: types.StringType,
			},
			"required": basetypes.BoolType{},
			"type":     basetypes.StringType{},
		}), diags
	}

	attributeTypes := map[string]attr.Type{
		"default":     basetypes.StringType{},
		"description": basetypes.StringType{},
		"name":        basetypes.StringType{},
		"options": basetypes.ListType{
			ElemType: types.StringType,
		},
		"required": basetypes.BoolType{},
		"type":     basetypes.StringType{},
	}

	if v.IsNull() {
		return types.ObjectNull(attributeTypes), diags
	}

	if v.IsUnknown() {
		return types.ObjectUnknown(attributeTypes), diags
	}

	objVal, diags := types.ObjectValue(
		attributeTypes,
		map[string]attr.Value{
			"default":     v.Default,
			"description": v.Description,
			"name":        v.Name,
			"options":     optionsVal,
			"required":    v.Required,
			"type":        v.ParamsType,
		})

	return objVal, diags
}

func (v ParamsValue) Equal(o attr.Value) bool {
	other, ok := o.(ParamsValue)

	if !ok {
		return false
	}

	if v.state != other.state {
		return false
	}

	if v.state != attr.ValueStateKnown {
		return true
	}

	if !v.Default.Equal(other.Default) {
		return false
	}

	if !v.Description.Equal(other.Description) {
		return false
	}

	if !v.Name.Equal(other.Name) {
		return false
	}

	if !v.Options.Equal(other.Options) {
		return false
	}

	if !v.Required.Equal(other.Required) {
		return false
	}

	if !v.ParamsType.Equal(other.ParamsType) {
		return false
	}

	return true
}

func (v ParamsValue) Type(ctx context.Context) attr.Type {
	return ParamsType{
		basetypes.ObjectType{
			AttrTypes: v.AttributeTypes(ctx),
		},
	}
}

func (v ParamsValue) AttributeTypes(ctx context.Context) map[string]attr.Type {
	return map[string]attr.Type{
		"default":     basetypes.StringType{},
		"description": basetypes.StringType{},
		"name":        basetypes.StringType{},
		"options": basetypes.ListType{
			ElemType: types.StringType,
		},
		"required": basetypes.BoolType{},
		"type":     basetypes.StringType{},
	}
}
